func (q *Queries) UpsertSourceMaterialForExtractedUnits(ctx context.Context, arg UpsertSourceMaterialForExtractedUnitsParams) (UpsertSourceMaterialForExtractedUnitsRow, error) {
	row := q.db.QueryRow(ctx, upsertSourceMaterialForExtractedUnits,
		arg.OwnerID,
		arg.Language,
		arg.SourceIdentifier,
		arg.Title,
		arg.MediaType,
		arg.ContentHash,
		arg.Content,
		arg.FullText,
	)
	var i UpsertSourceMaterialForExtractedUnitsRow
	err := row.Scan(
		&i.ID,
		&i.OwnerID,
		&i.Language,
		&i.SourceIdentifier,
		&i.Title,
		&i.MediaType,
		&i.ContentHash,
		&i.Content,
		&i.FullText,
		&i.CreatedAt,
	)
	return i, err
}
